// save_order_summary.js
const XLSX = require('xlsx');

const workbook = XLSX.readFile('testbed/data/order_summary.xlsx');
const sheet = workbook.Sheets['Orders'];

// Convert to CSV format
const csvContent = XLSX.utils.sheet_to_csv(sheet);

// Write to output file
const fs = require('fs');
const outputPath = 'testbed/data/order_summary_extracted.csv';
fs.writeFileSync(outputPath, csvContent, 'utf-8');

console.log('Saved extracted contents to: ' + outputPath);
console.log('Total lines (including header): ' + csvContent.split('\n').filter(l => l.trim()).length);
```

